mcp:tool-listener.mcp:parameters-schema:
{
  "type": "object",
  "required": ["appName", "environment"],
  "properties": {
    "appName": {
      "type": "string",
      "description": "Name of the MuleSoft application as it appears in Anypoint Runtime Manager."
    },
    "environment": {
      "type": "string",
      "description": "Anypoint Platform environment where the app is running (e.g. Production, Staging, Development)."
    },
    "jiraTicketId": {
      "type": "string",
      "description": "Optional Jira ticket ID to link assessment results back to a migration tracking ticket."
    }
  }
}

{
  "type": "object",
  "required": ["appName", "environment", "jiraTicketId", "approvedChangePlan"],
  "properties": {
    "appName": {
      "type": "string",
      "description": "Name of the MuleSoft application to upgrade."
    },
    "environment": {
      "type": "string",
      "description": "Anypoint Platform environment to upgrade the application in."
    },
    "jiraTicketId": {
      "type": "string",
      "description": "Jira ticket ID for this migration effort. Progress updates will be posted to this ticket."
    },
    "approvedChangePlan": {
      "type": "object",
      "description": "The changePlan object returned by assess_app, reviewed and approved by the user.",
      "properties": {
        "targetRuntime":     { "type": "string" },
        "targetJavaVersion": { "type": "string" },
        "filesToChange":     { "type": "array", "items": { "type": "string" } },
        "hasApiPolicies":    { "type": "boolean" },
        "hasCustomJavaCode": { "type": "boolean" },
        "hasLookupFunction": { "type": "boolean" }
      }
    }
  }
}

{
  "type": "object",
  "required": ["jobId"],
  "properties": {
    "jobId": {
      "type": "string",
      "description": "The jobId returned by start_upgrade. Format: job-{uuid}."
    }
  }
}
